P = P.concat([{"id":"x-technologijos-kurybai","external":true,"name":"Technologijos kūrybai (Technologies for creativity)","number":"2022-1-LT01-KA122-SCH-000078617","today":"KA122-SCH","action":"ka122","domain":"Schools","years":"2022–23","role":"Other lab","coordinator":{"name":"Vilniaus Vyturio pradine mokykla","country":"LT"},"goodPractice":true,"objective":"A Vilnius primary school sent teachers abroad to strengthen their STEAM skills ahead of a school renovation, so they could design new STEAM learning spaces and a project-based STEAM model for the school.","did":"Teachers came back trained in project-based learning and in using Lego robotics in class, and fed this into STEAM guidelines and the planning of the renovated school's learning spaces.","whyMakers":"It shows a school using a small KA122 grant to prepare staff before building a maker/STEAM space, which is an obvious door for a fablab to offer job-shadowing or courses.","url":"https://erasmus-plus.ec.europa.eu/projects/search/details/2022-1-LT01-KA122-SCH-000078617","extraUrl":null,"partnership":{"size":"One organisation, with hosts abroad","countries":["LT"],"roles":"Coordinated by Vilniaus Vyturio pradine mokykla (LT).","money":"EU grant: €10,750."}},{"id":"x-3d-printing-visually-impaired","external":true,"name":"3D printing can bring learning for visual impaired to life","number":"2023-1-MK01-KA122-SCH-000135045","today":"KA122-SCH","action":"ka122","domain":"Schools","years":"2023–24","role":"Other lab","coordinator":{"name":"drzavno uciliste za deca i mladi so osteten vid \"Dimitar Vlahov\"","country":"MK"},"goodPractice":true,"objective":"North Macedonia's school for visually impaired pupils trained its educators in 3D printing so they could make tactile teaching aids themselves.","did":"Staff gained 3D-printing skills and began producing tactile learning tools, which added to classroom resources and supported inclusion in both specialised and mainstream schools.","whyMakers":"Making accessible tactile aids is a concrete, fundable service a fablab can offer special-needs schools, through job-shadowing or training.","url":"https://erasmus-plus.ec.europa.eu/projects/search/details/2023-1-MK01-KA122-SCH-000135045","extraUrl":null,"partnership":{"size":"One organisation, with hosts abroad","countries":["MK"],"roles":"Coordinated by drzavno uciliste za deca i mladi so osteten vid \"Dimitar Vlahov\" (MK).","money":"EU grant: €12,330."}},{"id":"x-printing-feminist-world","external":true,"name":"Printing our feminist and sustainable world. Women in Science through 3D printing","number":"2024-1-IT02-KA122-ADU-000231790","today":"KA122-ADU","action":"ka122","domain":"Adults","years":"2024–25","role":"Other lab","coordinator":{"name":"SMART","country":"IT"},"goodPractice":true,"objective":"Staff mobility for non-formal adult educators, aimed at getting more women into science and technology by using 3D modelling and printing to make scientific ideas tangible.","did":"Staff took up new methods built on 3D modelling and printing, including a planned exhibition of prints about women in science, and the organisation reports more women in its community taking part in science activities.","whyMakers":"It shows how digital fabrication can carry a gender-inclusion goal in adult education, which suits a makerspace's own staff-mobility plan.","url":"https://erasmus-plus.ec.europa.eu/projects/search/details/2024-1-IT02-KA122-ADU-000231790","extraUrl":null,"partnership":{"size":"One organisation, with hosts abroad","countries":["IT"],"roles":"Coordinated by SMART (IT).","money":"EU grant: €57,090."}},{"id":"x-inclusive-space-makers","external":true,"name":"Inclusive Space Makers: Empowering All Abilities","number":"2023-3-ES02-KA153-YOU-000180663","today":"KA153-YOU","action":"youth","domain":"Youth","years":"2024","role":"Other lab","coordinator":{"name":"Associació Alba","country":"ES"},"goodPractice":true,"objective":"A Catalan disability-inclusion association sent youth workers, including a facilitator with a disability, on job-shadowing with a French digital-youth organisation to learn how to run inclusive community maker spaces.","did":"Youth workers came back with hands-on experience of setting up and running community maker spaces, and the association is launching its own FabLab built around 3D printing.","whyMakers":"For under EUR 5,000, a KA153 job-shadowing led to a new inclusive fablab: a cheap first step for a new makerspace.","url":"https://erasmus-plus.ec.europa.eu/projects/search/details/2023-3-ES02-KA153-YOU-000180663","extraUrl":"https://www.aalba.cat","partnership":{"size":"2 organisations","countries":["ES","FR"],"roles":"Coordinated by Associació Alba (ES).","money":"EU grant: €4,760."}},{"id":"x-maker-movement-ye","external":true,"name":"Maker Movement","number":"2022-3-PT02-KA152-YOU-000098170","today":"KA152-YOU","action":"youth","domain":"Youth","years":"2023","role":"Other lab","coordinator":{"name":"Frutífera Oliveira de Azeméis","country":"PT"},"goodPractice":true,"objective":"A youth exchange that introduced young people to the maker movement as an answer to overconsumption, linking making and repurposing with resource conservation.","did":"Participants built making and teamwork skills, learned about recycling practices and initiatives in each other's countries, and took up a maker mindset focused on reuse.","whyMakers":"It frames the maker movement itself as the theme of a youth exchange, a format any fablab can host with partners from eight countries.","url":"https://erasmus-plus.ec.europa.eu/projects/search/details/2022-3-PT02-KA152-YOU-000098170","extraUrl":null,"partnership":{"size":"8 organisations","countries":["PT","BG","CZ","IT","TR","HU","ES","HR"],"roles":"Coordinated by Frutífera Oliveira de Azeméis (PT).","money":"EU grant: €38,092."}},{"id":"x-maker-abc","external":true,"name":"Maker ABC","number":"2021-2-RO01-KA210-ADU-000051270","today":"KA210-ADU","action":"ka210","domain":"Adults","years":"2022–23","role":"Other lab","coordinator":{"name":"NOD Makerspace SRL","country":"RO"},"goodPractice":true,"objective":"A Bucharest makerspace and two Barcelona partners (including IAAC, home of Fab Lab Barcelona) studied the European maker movement through three lenses: entrepreneurship, the SDGs and community building.","did":"They produced a dictionary-style guide of about 130 maker-movement terms (PDF and website), plus three adult-learning training events and three dissemination events for makerspace coordinators, makers and educators.","whyMakers":"It is a makerspace-led KA210 run by and for makerspaces, and a model for a first small partnership between fablabs.","url":"https://erasmus-plus.ec.europa.eu/projects/search/details/2021-2-RO01-KA210-ADU-000051270","extraUrl":"http://makerabc.eu","partnership":{"size":"3 organisations","countries":["RO","ES"],"roles":"Coordinated by NOD Makerspace SRL (RO).","money":"EU grant: €60,000."}},{"id":"x-prototyping-designerly","external":true,"name":"Prototyping: Designerly way of creating your business","number":"2022-1-DK01-KA210-ADU-000084605","today":"KA210-ADU","action":"ka210","domain":"Adults","years":"2022–23","role":"Other lab","coordinator":{"name":"Vejle Kommune, Innovation & Entreprenørskab","country":"DK"},"goodPractice":true,"objective":"Two fablabs, FabLab Spinderihallerne (run by Vejle municipality) and Verket FabLab in Norway, swapped methods for using prototyping and digital fabrication to support small creative entrepreneurs.","did":"The partners completed five study trips, five partner meetings and a final international seminar, and both fablabs gained new methods and educational formats that combine prototyping, digital fabrication and design thinking for students and start-ups.","whyMakers":"It is a two-partner fablab-to-fablab exchange focused on entrepreneurship, the simplest KA210 set-up there is.","url":"https://erasmus-plus.ec.europa.eu/projects/search/details/2022-1-DK01-KA210-ADU-000084605","extraUrl":null,"partnership":{"size":"2 organisations","countries":["DK","NO"],"roles":"Coordinated by Vejle Kommune, Innovation & Entreprenørskab (DK).","money":"EU grant: €60,000."}},{"id":"x-jedi-track","external":true,"name":"Jeunes en Quête de Science pour les Territoires (JEDI-TRACK)","number":"2023-3-FR02-KA210-YOU-000170800","today":"KA210-YOU","action":"ka210","domain":"Youth","years":"2024–25","role":"Other lab","coordinator":{"name":"Les Emulsionneurs","country":"FR"},"goodPractice":true,"objective":"Helped young people from underprivileged neighbourhoods design and run citizen-science actions about local quality of life, building their civic engagement and digital skills along the way.","did":"Field work was turned into a replicable method and practical resources that socio-educational facilitators can use to run citizen-science activities with young people.","whyMakers":"Citizen science and DIY sensing are natural fablab activities, and this shows them packaged as a youth KA210.","url":"https://erasmus-plus.ec.europa.eu/projects/search/details/2023-3-FR02-KA210-YOU-000170800","extraUrl":null,"partnership":{"size":"3 organisations","countries":["FR","BE","FR"],"roles":"Coordinated by Les Emulsionneurs (FR).","money":"EU grant: €60,000."}},{"id":"x-re4vet","external":true,"name":"Reverse Engineering for Vocational Education and Training","number":"2022-2-DE02-KA210-VET-000100472","today":"KA210-VET","action":"ka210","domain":"VET","years":"2023–24","role":"Other lab","coordinator":{"name":"Berufsbildende Schule Bad Dürkheim","country":"DE"},"goodPractice":true,"objective":"A German vocational school, a Spanish partner and e-Nable Greece developed and tested a way of teaching reverse engineering, using 3D scanning and 3D printing, to VET learners.","did":"The partners produced a handbook, a workshop and a self-paced online course with quizzes, piloted with VET students and teachers.","whyMakers":"3D scanning and printing for reverse engineering is everyday fablab practice, and here it became a VET curriculum with a maker NGO (e-Nable) as partner.","url":"https://erasmus-plus.ec.europa.eu/projects/search/details/2022-2-DE02-KA210-VET-000100472","extraUrl":null,"partnership":{"size":"3 organisations","countries":["DE","ES","GR"],"roles":"Coordinated by Berufsbildende Schule Bad Dürkheim (DE).","money":"EU grant: €60,000."}},{"id":"x-fabyouth","external":true,"name":"Digital Fabrication and Service Learning for Youth (FabYouth)","number":"2024-1-RO01-KA210-YOU-000255823","today":"KA210-YOU","action":"ka210","domain":"Youth","years":"2024–26","role":"Other lab","coordinator":{"name":"Asociația Comunitatea Educație pentru Știință","country":"RO"},"goodPractice":false,"objective":"A Romanian science-education association (SciFablab Măgurele) and Bulgaria's National STEM Center involved young people in designing, testing and presenting a kit-based non-formal STEM programme.","did":"The project produced the open FabYouth STEM Explorer Kit (modular sensors, a data-logging app, lessons and a multilingual website) and a robotics and science curriculum tested at SciFablab and the NSC.","whyMakers":"It produced an open-hardware, reproducible fablab kit as a youth KA210 output, a model for documenting results that others can reuse.","url":"https://erasmus-plus.ec.europa.eu/projects/search/details/2024-1-RO01-KA210-YOU-000255823","extraUrl":"https://scifablab.gitlab.io/fabyouth-project/fabyouth-stem-explorer-kit/ro/","partnership":{"size":"2 organisations","countries":["RO","BG"],"roles":"Coordinated by Asociația Comunitatea Educație pentru Știință (RO).","money":"EU grant: €60,000."}},{"id":"x-green-fab-lab","external":true,"name":"Introduction of a GREEN FAB LAB educational concept in secondary schools","number":"2023-1-MK01-KA220-SCH-000165118","today":"KA220-SCH","action":"ka220","domain":"Schools","years":"2023–25","role":"Other lab","coordinator":{"name":"Foundation CEED Macedonia","country":"MK"},"goodPractice":true,"objective":"Advanced STEM teaching in secondary schools by combining problem-based learning and design thinking with environmental challenges, and by setting up three \"Green Fab Labs\" in partner schools.","did":"The project delivered teacher manuals and a recommendations document, trained teachers in PBL, design thinking and the fab lab model, produced 18 lesson plans, and ran student-team activities.","whyMakers":"It is a blueprint for putting fab labs inside schools with a green focus, the kind of KA220 where a fablab can be the technical partner.","url":"https://erasmus-plus.ec.europa.eu/projects/search/details/2023-1-MK01-KA220-SCH-000165118","extraUrl":null,"partnership":{"size":"6 organisations","countries":["MK","MK","GR","PL"],"roles":"Coordinated by Foundation CEED Macedonia (MK).","money":"EU grant: €120,000."}},{"id":"x-makeredu","external":true,"name":"MakerEDU – Handlungsorientierte Medienkompetenz für pädagogische Fachkräfte","number":"2021-1-DE02-KA220-VET-000032956","today":"KA220-VET","action":"ka220","domain":"VET","years":"2021–23","role":"Other lab","coordinator":{"name":"E&G Projekt Agentur GmbH","country":"DE"},"goodPractice":true,"objective":"Trained educators, especially in rural areas, to act as maker-education multipliers who can run practical makerspace activities with children and young people without heavy preparation.","did":"The project produced a training handbook on hands-on media skills and maker education, and a requirements catalogue with a space-use concept to help organisations set up their own makerspaces.","whyMakers":"Its outputs are a toolkit for opening and running a rural makerspace, built with Technolab Leiden as a maker partner.","url":"https://erasmus-plus.ec.europa.eu/projects/search/details/2021-1-DE02-KA220-VET-000032956","extraUrl":null,"partnership":{"size":"4 organisations","countries":["DE","SK","RS","NL"],"roles":"Coordinated by E&G Projekt Agentur GmbH (DE).","money":"EU grant: €222,001."}},{"id":"x-adapt4future","external":true,"name":"ADaPT4Future: ADult People create Technologies for their Future","number":"2021-1-LT01-KA220-ADU-000026995","today":"KA220-ADU","action":"ka220","domain":"Adults","years":"2021–23","role":"Other lab","coordinator":{"name":"VšĮ Robotikos mokykla","country":"LT"},"goodPractice":true,"objective":"A Lithuanian robotics school, a public library, a Polish foundation and an Italian municipality worked to build 3D-printing and design-thinking skills among adults and to strengthen adult educators' ability to teach them.","did":"The project produced an open methodological toolkit (learner materials, educator guidelines and research tools) and ran local 3D workshops with 213 adult learners, more than half of them with fewer opportunities.","whyMakers":"It shows a maker-education provider partnering with a library and a municipality to bring 3D printing to adult learners, with measured outcomes.","url":"https://erasmus-plus.ec.europa.eu/projects/search/details/2021-1-LT01-KA220-ADU-000026995","extraUrl":"https://toolkit.adapt4future.gaminu.eu","partnership":{"size":"4 organisations","countries":["LT","PL","LT","IT"],"roles":"Coordinated by VšĮ Robotikos mokykla (LT).","money":"EU grant: €136,194.78."}},{"id":"x-empowertech","external":true,"name":"Empowering Young People with Down Syndrome through Technology (EmpowerTech)","number":"2023-2-IT03-KA220-YOU-000178021","today":"KA220-YOU","action":"ka220","domain":"Youth","years":"2024–25","role":"Other lab","coordinator":{"name":"A Ruota Libera APS","country":"IT"},"goodPractice":true,"objective":"Mapped the barriers that keep young people with Down syndrome out of technology learning, and trained youth workers in inclusive tinkering, basic coding and mentoring.","did":"The project produced a research report on good practices, an e-learning course for youth workers, a training format with session plans, an accessible web platform linking coding to hands-on electronics, and blended pilots.","whyMakers":"It turns inclusive tinkering and electronics into a structured youth-work offer, which is relevant to any makerspace working on accessibility.","url":"https://erasmus-plus.ec.europa.eu/projects/search/details/2023-2-IT03-KA220-YOU-000178021","extraUrl":"https://www.asinochilegge.org","partnership":{"size":"4 organisations","countries":["IT","DE","GR","LV"],"roles":"Coordinated by A Ruota Libera APS (IT).","money":"EU grant: €120,000."}},{"id":"x-communities-go-circular","external":true,"name":"Communities Go Circular (CGC)","number":"101081655","today":"CERV-2022-CITIZENS-CIV","action":"cerv","domain":"Community","years":"2022–24","role":"Other lab","coordinator":{"name":"Udruga Zelena Istra","country":"HR"},"goodPractice":false,"objective":"Engaged citizens, NGOs and decision-makers in Croatia, Slovenia and Italy in building zero-waste circular communities, with a particular focus on right-to-repair policy.","did":"The project ran 57 activities, including 37 reuse and repair workshops, and produced conferences, a mobile exhibition, policy guidelines and a proposal to government on reuse and repair centres.","whyMakers":"It shows repair-café and reuse work funded as civic participation under CERV rather than Erasmus+, with a social-enterprise creative hub (KNOF) among the partners.","url":"https://ec.europa.eu/info/funding-tenders/opportunities/portal/screen/opportunities/projects-details/43251589/101081655/CERV","extraUrl":null,"partnership":{"size":"5 organisations","countries":["HR","HR","SI","IT"],"roles":"Coordinated by Udruga Zelena Istra (HR).","money":"EU grant: €192,935."}},{"id":"x-redesign-belonging","external":true,"name":"Redesign Belonging (ReBel)","number":"101146813","today":"CERV-2023-CITIZENS-CIV","action":"cerv","domain":"Community","years":"2024–26","role":"Other lab","coordinator":{"name":"Laurea-ammattikorkeakoulu Oy","country":"FI"},"goodPractice":false,"objective":"Paired long-settled migrant women with professional designers to co-create solutions to belonging and solidarity challenges, using service-design methods.","did":"The project ran research dialogues and co-creation workshops in several countries and produced reports, visual outputs and recommendations aimed at integration policy.","whyMakers":"It shows how co-design and making-with-communities methods can be funded under CERV citizens' engagement, with What Design Can Do as a design partner.","url":"https://ec.europa.eu/info/funding-tenders/opportunities/portal/screen/opportunities/projects-details/43251589/101146813/CERV","extraUrl":null,"partnership":{"size":"4 organisations","countries":["FI","NL","ES","FI"],"roles":"Coordinated by Laurea-ammattikorkeakoulu Oy (FI).","money":"EU grant: €406,135."}},{"id":"x-teca","external":true,"name":"TECA – Technological Empowerment in Creative Arts","number":"101174389","today":"CREA-CULT-2024-COOP-1","action":"crea","domain":"Culture","years":"2024–27","role":"Other lab","coordinator":{"name":"Iceberg Plus SRL","country":"RO"},"goodPractice":false,"objective":"Builds digital literacy among artists in Romania, Serbia and Bosnia and Herzegovina so they can bring technology into their artwork, using a method that temporarily turns makerspaces and FabLabs into venues for artistic work.","did":"Still running (ends January 2027), so no results are published yet. Planned outputs are an online collaboration platform, expert-led workshops and digital-art labs held on site and online, and a reusable method for hosting artists in maker spaces.","whyMakers":"It casts fablabs as hosts for artists and has a Bosnian digital-fabrication lab as a partner, a small-scale Creative Europe model that suits fablabs wanting an arts strand.","url":"https://culture.ec.europa.eu/creative-europe/projects/search/details/101174389","extraUrl":"https://www.iceberg.plus","partnership":{"size":"3 organisations","countries":["RO","BA","RS"],"roles":"Coordinated by Iceberg Plus SRL (RO).","money":"EU grant: €193,511.64."}},{"id":"x-bio-awakening","external":true,"name":"Bio Awakening – developing bio-art practices in Western Balkan","number":"101128497","today":"CREA-CULT-2023-COOP-1","action":"crea","domain":"Culture","years":"2023–25","role":"Other lab","coordinator":{"name":"Udruženje građana Reaktor","country":"RS"},"goodPractice":false,"objective":"Brought artists, scientists and curators together to co-create environment-friendly bio-art practices and productions and to raise awareness of the Green Deal, with a focus on the Western Balkans.","did":"The plan included a bio-art forum, study visits to labs in Ljubljana and Dubrovnik, DIY and mobile-lab workshops, four interactive bio-art installations at festivals in Novi Sad and Pecka, a regional network of bio-art labs, a film and a white paper. The platform publishes no results for the project.","whyMakers":"It shows bio-art and mobile or DIY lab work funded as a small-scale cooperation project, relevant to fablabs working with biomaterials.","url":"https://culture.ec.europa.eu/creative-europe/projects/search/details/101128497","extraUrl":null,"partnership":{"size":"5 organisations","countries":["RS","SI","HR","BA","RS"],"roles":"Coordinated by Udruženje građana Reaktor (RS).","money":"EU grant: €200,000."}}]);
